DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('private.base_validate(jsonb)'::regprocedure) INTO d;d:=replace(d,$s$IF nullif(r->>'ends_at','') IS NOT NULL AND (r->>'ends_at')::timestamptz<=coalesce(nullif(r->>'starts_at','')::timestamptz,now()) AND coalesce((r->>'active')::boolean,false) THEN RAISE EXCEPTION 'Thời hạn không hợp lệ.';END IF;$s$,$s$IF nullif(r->>'ends_at','') IS NOT NULL THEN PERFORM (r->>'ends_at')::timestamptz;END IF;$s$);EXECUTE d;END $patch$;
CREATE OR REPLACE FUNCTION private.base_tier1(u uuid,p text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN private.base_supported(p) THEN private.base_decision(u,p,private.base_config()) ELSE 'NOT_CONFIGURED' END $$;